items.content:
body {
  margin: 0;
  font-family: system-ui, sans-serif;
  background: #101820;
  color: #f2f2f2;
}

.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.1); }
  100% { transform: scale(1); }
}

.combo {
  animation: pulse 0.3s ease-in-out;
}

.nav a {
  text-decoration: none;
  color: inherit;
}

.nav a.active {
  border-bottom: 2px solid currentColor;
}

.cursor {
  display: inline-block;
  width: 2px;
  height: 1.2em;
  background: currentColor;
  animation: blink 1s steps(1) infinite;
}

.overlay {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.6);
  z-index: 100;
}

.progress {
  height: 8px;
  background: #333;
}

.progress > .bar {
  width: 60%;
  height: 100%;
  background: linear-gradient(90deg, #e10600, #ffc500);
  transition: width 0.2s;
}

ul.keyboard > li:nth-child(odd) {
  background: #222;
}

ul.keyboard > li:first-child,
ul.keyboard > li:last-child {
  font-weight: bold;
}

.track {
  width: min(100%, 960px);
  margin-inline: auto;
  padding: clamp(8px, 2vw, 24px);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
